#ifndef LIBHDFSPP_TOOLS_HDFS_COPY_TO_LOCAL
#define LIBHDFSPP_TOOLS_HDFS_COPY_TO_LOCAL

#include <string>

#include <boost/program_options.hpp>

#include "hdfs-tool.h"

namespace hdfs::tools {
/**
 * {@class CopyToLocal} is an {@class HdfsTool} that copies the source file from
 * HDFS to the destination file on the local file system.
 */
class CopyToLocal : public HdfsTool {
public:
  /**
   * {@inheritdoc}
   */
  CopyToLocal(int argc, char **argv);

  // Abiding to the Rule of 5
  CopyToLocal(const CopyToLocal &) = default;
  CopyToLocal(CopyToLocal &&) = default;
  CopyToLocal &operator=(const CopyToLocal &) = delete;
  CopyToLocal &operator=(CopyToLocal &&) = delete;
  ~CopyToLocal() override = default;

  /**
   * {@inheritdoc}
   */
  [[nodiscard]] std::string GetDescription() const override;

  /**
   * {@inheritdoc}
   */
  [[nodiscard]] bool Do() override;

protected:
  /**
   * {@inheritdoc}
   */
  [[nodiscard]] bool Initialize() override;

  /**
   * {@inheritdoc}
   */
  [[nodiscard]] bool ValidateConstraints() const override { return argc_ > 2; }

  /**
   * {@inheritdoc}
   */
  [[nodiscard]] bool HandleHelp() const override;

  /**
   * Handle the path to the source file and the path to the destination file.
   *
   * @param source The path to the source file on HDFS.
   * @param target The path to the destination file on the local file system.
   *
   * @return A boolean indicating the result of this operation.
   */
  [[nodiscard]] virtual bool HandlePath(const std::string &source,
                                        const std::string &target) const;

  /**
   * @return The name of the tool.
   */
  [[nodiscard]] virtual std::string GetToolName() const;

  /**
   * @return Whether the source file must be deleted after it has been copied
   * to the destination file.
   */
  [[nodiscard]] virtual bool GetMoveFlag() const;

private:
  /**
   * A boost data-structure containing the description of positional arguments
   * passed to the command-line.
   */
  po::positional_options_description pos_opt_desc_;
};
} // namespace hdfs::tools
#endif
