   * {@inheritdoc}
   */
  [[nodiscard]] std::string GetDescription() const override;

protected:
  /**
   * {@inheritdoc}
   */
  [[nodiscard]] std::string GetToolName() const override;

  /**
   * {@inheritdoc}
   */
  [[nodiscard]] bool GetMoveFlag() const override;
};
} // namespace hdfs::tools
